((globalThis.__tukSourceBundles ??= Object.create(null))["main-app.js"] ??= []).push("          // 2. 转为 Base64 字符串 (天然包含大小写字母和数字)\r\n          let base64 = CryptoJS.enc.Base64.stringify(rawHash);\r\n\r\n          // 3. 截取前 12 位 (增加长度)\r\n          let generated = base64.substring(0, 12);\r\n\r\n          // 4. 强制插入特殊符号 (增强复杂度)\r\n          // 将字符串转为数组进行替换\r\n          let chars = generated.split(\"\");\r\n          chars[2] = \"@\"; // 第3位强制变为 @\r\n          chars[7] = \"!\"; // 第8位强制变为 !\r\n\r\n          // 重新组合\r\n          const correctPassword = chars.join(\"\");\r\n\r\n          // console.log(\"正确密码应为:\", correctPassword); // 调试用，上线可注释\r\n          return pwd.trim() === correctPassword;\r\n        }\r\n\r\n        // 项目名与入口目录共同构成命名空间：同域不同项目路径、不同本地目录均不会串用数据。\r\n        const storageProjectRoot = new URL(\"./\", window.location.href);\r\n        const STORAGE_PROJECT_ID = `tuk-phone:${storageProjectRoot.protocol}//${storageProjectRoot.host}${storageProjectRoot.pathname}`;\r\n        const LEGACY_DATABASE_NAME = \"GeminiChatDB\";\r\n\r\n        function getScopedStorageKey(key) {\r\n          return `ephone:${STORAGE_PROJECT_ID}:${key}`;\r\n        }\r\n\r\n        const projectStorage = {\r\n          getItem(key) {\n            return localStorage.getItem(getScopedStorageKey(key));\n          },\r\n          setItem(key, value) {\r\n            localStorage.setItem(getScopedStorageKey(key), value);\r\n          },\r\n          removeItem(key) {\r\n            localStorage.removeItem(getScopedStorageKey(key));\r\n          },\r\n          clear() {\r\n            const prefix = `${getScopedStorageKey(\"\")}`;\r\n            const scopedKeys = [];\r\n            for (let index = 0; index < localStorage.length; index += 1) {\r\n              const key = localStorage.key(index);\r\n              if (key && key.startsWith(prefix)) scopedKeys.push(key);\r\n            }\r\n            scopedKeys.forEach((key) => localStorage.removeItem(key));\r\n            localStorage.setItem(getScopedStorageKey(\"__cleared__\"), \"true\");\r\n          },\r\n        };\r\n\r\n        function getProjectDatabaseName(userId) {\r\n          return `${LEGACY_DATABASE_NAME}::${STORAGE_PROJECT_ID}::${encodeURIComponent(String(userId))}`;\r\n        }\r\n\r\n        async function legacyDatabaseExists() {\r\n          try {\r\n            if (typeof indexedDB.databases === \"function\") {\r\n              const databases = await indexedDB.databases();\r\n              return databases.some((database) => database.name === LEGACY_DATABASE_NAME);\r\n            }\r\n          } catch (error) {\r\n            console.warn(\"[System] 无法枚举本地数据库，将使用兼容检测：\", error);\r\n          }\r\n          return Dexie.exists(LEGACY_DATABASE_NAME);\r\n        }\r\n\r\n        async function readLegacyDatabase() {\r\n          return new Promise((resolve, reject) => {\r\n            const request = indexedDB.open(LEGACY_DATABASE_NAME);\r\n            request.onerror = () => reject(request.error || new Error(\"无法读取旧版本地数据。\"));\r\n            request.onsuccess = () => {\r\n              const legacyDb = request.result;\r\n              const storeNames = Array.from(legacyDb.objectStoreNames);\r\n              if (storeNames.length === 0) {\r\n                legacyDb.close();\r\n                resolve({});\r\n                return;\r\n              }\r\n\r\n              const transaction = legacyDb.transaction(storeNames, \"readonly\");\r\n              const recordsByStore = {};\r\n              let pendingCount = storeNames.length;\r\n              let finished = false;\r\n              const finish = (error) => {\r\n                if (finished) return;\r\n                finished = true;\r\n                legacyDb.close();\r\n                if (error) reject(error);\r\n                else resolve(recordsByStore);\r\n              };\r\n\r\n              transaction.onerror = () => finish(transaction.error || new Error(\"读取旧版本地数据失败。\"));\r\n              transaction.onabort = () => finish(transaction.error || new Error(\"读取旧版本地数据被中止。\"));\r\n\r\n              storeNames.forEach((storeName) => {\r\n                const getAllRequest = transaction.objectStore(storeName).getAll();\r\n                getAllRequest.onerror = () => finish(getAllRequest.error || new Error(`读取旧数据表 ${storeName} 失败。`));\r\n                getAllRequest.onsuccess = () => {\r\n                  recordsByStore[storeName] = getAllRequest.result || [];\r\n                  pendingCount -= 1;\r\n                  if (pendingCount === 0) finish();\r\n                };\r\n              });\r\n            };\r\n          });\r\n        }\r\n\r\n        function normalizeLegacyRecords(storeName, records) {\r\n          if (storeName !== \"customAvatarFrames\") return records;\r\n          return records.map((record, index) =>\r\n            record && record.id !== undefined && record.id !== null\r\n              ? record\r\n              : { ...record, id: `legacy-frame-${index}` },\r\n          );\r\n        }\r\n\r\n        async function migrateLegacyDatabaseIfNeeded(userId) {\r\n          const migrationKey = getScopedStorageKey(`legacy-db-migrated:${userId}`);\r\n          if (localStorage.getItem(migrationKey) === \"true\") return;\r\n          const legacyOwnerKey = getScopedStorageKey(\"legacy-db-owner\");\r\n          const legacyOwner = localStorage.getItem(legacyOwnerKey);\r\n          if (legacyOwner && legacyOwner !== String(userId)) {\r\n            localStorage.setItem(migrationKey, \"true\");\r\n            return;\r\n          }\r\n          if (!(await legacyDatabaseExists())) {\r\n            localStorage.setItem(migrationKey, \"true\");\r\n            return;\r\n          }\r\n\r\n          const legacyRecords = await readLegacyDatabase();\r\n          const targetTables = db.tables.filter((table) =>\r\n            Object.prototype.hasOwnProperty.call(legacyRecords, table.name),\r\n          );\r\n\r\n          if (targetTables.length > 0) {\r\n            await db.transaction(\"rw\", ...targetTables, async () => {\r\n              for (const table of targetTables) {\r\n                const records = normalizeLegacyRecords(\r\n                  table.name,\r\n                  legacyRecords[table.name],\r\n                );\r\n                if (records.length > 0) await table.bulkPut(records);\r\n              }\r\n            });\r\n          }\r\n\r\n          localStorage.setItem(migrationKey, \"true\");\r\n          localStorage.setItem(legacyOwnerKey, String(userId));\r\n          console.log(`[System] 已将旧版本地数据迁移到用户 ${userId} 的独立数据库。`);\r\n        }\r\n\r\n        // 动态初始化数据库函数\r\n        async function initDatabase(userId) {\r\n          db = new Dexie(getProjectDatabaseName(userId));\r\n          db.version(66).stores({\n            // 版本号从 51 升级到 52\r\n            chats:\r\n              \"&id, isGroup, groupId, ownerId, isPinned, characterPhoneData, latestInnerVoice, innerVoiceHistory, loversSpaceData.emotionDiaries, settings.summary, settings.weiboNickname, settings.innerVoiceHideHeaderBorder, settings.innerVoiceAdopterLabelFormat, interactionStats, unlockedSymbols, settings.selectedIntimacyBadge\",\r\n            apiConfig: \"&id\",\r\n            globalSettings: \"&id, activeThemeId\",\r\n            userStickers: \"&id, url, name, categoryId\",\r\n            userStickerCategories: \"++id, &name\",\r\n            charStickers: \"&id, url, name\",\r\n            worldBooks: \"&id, name, categoryId\",\r\n            worldBookCategories: \"++id, name\",\r\n            musicLibrary: \"&id\",\r\n            personaPresets: \"&id\",\r\n            qzoneSettings: \"&id\",\r\n            qzonePosts: \"++id, authorId, timestamp\",\r\n            qzoneAlbums: \"++id, name, createdAt\",\r\n            qzonePhotos: \"++id, albumId\",\r\n            favorites: \"++id, type, timestamp, originalTimestamp\",\r\n            qzoneGroups: \"++id, name\",\r\n            memories: \"++id, chatId, timestamp, type, targetDate\",\r\n            callRecords: \"++id, chatId, timestamp, customName\",\r\n            customAvatarFrames: \"&id, name, url\",\r\n            themes: \"++id, name, css\",\r\n            apiPresets: \"++id, name, proxyUrl\",\r\n            bubbleStylePresets: \"++id, name, css\",\r\n            fontPresets: \"&id, name, url\",\r\n            homeScreenPresets: \"++id, name\",\r\n            weiboPosts: \"++id, authorId, timestamp\",\r\n            forumGroups: \"++id, name, worldview, *categories\",\r\n            forumPosts:\r\n              \"++id, groupId, timestamp, *categories, seriesId, lengthType, chapterIndex\",\r\n            forumComments: \"++id, postId, timestamp\",\r\n            forumCategories: \"++id, name\",\r\n            forumSeries:\r\n              \"++id, groupId, isFollowed, updatedAt, bookshelfAddedAt\",\r\n            forumChapters: \"++id, seriesId, chapterIndex, createdAt, postId\",\r\n            tarotReadings: \"++id, timestamp\",\r\n            pomodoroSessions: \"++id, chatId, startTime\",\r\n            scriptKillScripts: \"++id, name, isBuiltIn\",\r\n            taobaoProducts: \"++id, name, category\",\r\n            taobaoOrders: \"++id, productId, timestamp\",\r\n            taobaoCart: \"++id, productId\",\r\n            userWalletTransactions: \"++id, timestamp\",\r\n            charPhonePresets: \"++id, name\",\r\n            ludoQuestionBanks: \"++id, name\",\r\n            ludoQuestions: \"++id, bankId, text, type\",\r\n            datingScenes: \"&uid, imageUrl\",\r\n            datingPresets: \"++id, name, settings.spriteGroupId\",\r\n            datingSpriteGroups: \"++id, name\",\r\n            datingSprites: \"++id, groupId, description, url\",\r\n            datingHistory: \"++id, characterId, timestamp\",\r\n            offlinePresets: \"++id, name\",\r\n            elemeFoods: \"++id, name, category\",\r\n            elemeOrders: \"++id, recipientId, timestamp\",\r\n            studioScripts: \"++id, name\",\r\n            studioHistory: \"++id, timestamp\",\r\n            studioSessions: \"&id, status, updatedAt, scriptId, aiChatId\",\r\n            studioMemories: \"&id, aiChatId, createdAt, sessionId\",\r\n            tukeyAccounts: \"++id, category, type\", // 这是你已有的，保持不变\r\n            tukeyAccountingGroups: \"&id\", // 记账群聊设置 (id, name, members, replySettings)\r\n            tukeyAccountingRecords:\r\n              \"++id, groupId, timestamp, isRepliedTo, accountId\",\r\n            tukeyAccountingReplies: \"++id, recordId, charId\", // AI的回复记录\r\n            tukeyUserSettings: \"&id\",\r\n            tukeyCustomConfig: \"&id\",\r\n            auroraBooks: \"++id, title, content, addedAt\",\r\n            passerbyAvatars: \"++id, url\",\r\n            clawMachineDolls: \"++id, url\",\r\n            mcpConnections: \"&id, type, enabled, status, updatedAt\",\r\n            mcpSecrets: \"&id, updatedAt\",\r\n            mcpCapabilities: \"&id, connectionId, kind, name, updatedAt\",\r\n            mcpActivities: \"&id, connectionId, chatId, status, createdAt\",\r\n            mcpSubscriptions: \"&id, connectionId, uri, updatedAt\",\r\n            mcpTasks: \"&id, connectionId, status, updatedAt\",\r\n            mcpApprovals: \"&id, connectionId, toolName, scope, updatedAt\",\r\n            mcpSettings: \"&id\",\r\n            memorySettings: \"&id, chatId, updatedAt\",\r\n            memoryVectors: \"&id, chatId, sourceType, timestamp, provider, contentHash\",\r\n            memoryFacts: \"&id, chatId, status, category, updatedAt, [chatId+status]\",\n            memoryRecallLogs: \"&id, chatId, timestamp, mode\",\n            promptSettings: \"&id, updatedAt\",\n            promptItems: \"&id, featureId, kind, updatedAt\",\n            promptPresets: \"&id, name, updatedAt\",\n            promptBindings: \"&id, scopeType, scopeId, featureId\",\n            promptDiagnostics: \"++id, timestamp, featureId\",\n          });\n          window.db = db;\n          await db.open();\n          // 不再自动读取通用的 GeminiChatDB。该数据库可能属于同源运行的\n          // xinyuan330 或其他项目；世界书等旧数据只能由用户在诊断工具中\n          // 主动选择并确认后，以只读副本的方式导入。\n          console.log(`[System] 已加载用户 ${userId} 的独立数据库`);\n        }\r\n        // === 修改结束 ===\r\n\r\n        // ===================================================================\r\n        // 3. 所有功能函数定义\r\n        // ===================================================================\r\n\r\n        /**\r\n         * 切换语音消息的文字显示/隐藏\r\n         * @param {HTMLElement} bubble - 被点击的语音消息的 .message-bubble 元素\r\n         */\r\n        function toggleVoiceTranscript(bubble) {\r\n          if (!bubble) return;\r\n\r\n          const transcriptEl = bubble.querySelector(\".voice-transcript\");\r\n          if (!transcriptEl) return;\r\n\r\n          // 核心逻辑：直接检查文字区域当前是不是显示状态\r\n          const isCurrentlyExpanded = transcriptEl.style.display === \"block\";\r\n\r\n          if (isCurrentlyExpanded) {\r\n            // 如果是展开的，就直接收起来\r\n            transcriptEl.style.display = \"none\";\r\n          } else {\r\n            // 如果是收起的，就执行展开流程\r\n\r\n            // 1. 先显示一个“正在转写”的提示，给用户即时反馈\r\n            transcriptEl.textContent = \"正在转文字...\";\r\n            transcriptEl.style.display = \"block\";\r\n\r\n            // 2. 模拟一个短暂的“识别”过程\r\n            setTimeout(() => {\r\n              // 再次检查元素是否还在页面上，防止用户切换聊天导致错误\r\n              if (document.body.contains(transcriptEl)) {\r\n                // 获取并显示真正的转写文字\r\n                const voiceText = bubble.dataset.voiceText || \"(无法识别)\";\r\n                transcriptEl.textContent = voiceText;\r\n              }\r\n            }, 300); // 300毫秒的延迟，感觉更灵敏\r\n          }\r\n        }\r\n\r\n        /**\r\n         * 【V2智能版】应用指定的主题，并智能刷新当前打开的任何界面\r\n         * @param {string} theme - 'light' 或 'dark'\r\n         */\r\n        function applyTheme(theme) {\r\n          const phoneScreen = document.getElementById(\"phone-screen\");\r\n          const toggleSwitch = document.getElementById(\"theme-toggle-switch\");\r\n\r\n          const isDark = theme === \"dark\";\r\n\r\n          // 核心操作：为手机屏幕添加或移除 .dark-mode 类\r\n          phoneScreen.classList.toggle(\"dark-mode\", isDark);\r\n\r\n          // 同步开关的状态\r\n          if (toggleSwitch) {\r\n            toggleSwitch.checked = isDark;\r\n          }\r\n\r\n          // 保存用户的选择\r\n          projectStorage.setItem(\"ephone-theme\", theme);\r\n\r\n          // 不再只关心聊天界面，而是找出当前究竟是哪个界面处于激活状态\r\n          const activeScreen = document.querySelector(\".screen.active\");\r\n          if (!activeScreen) return; // 如果找不到，就退出\r\n\r\n          // 根据当前激活的界面ID，调用它专属的刷新函数\r\n          switch (activeScreen.id) {\r\n            case \"chat-interface-screen\":\r\n              if (state.activeChatId) {\r\n                renderChatInterface(state.activeChatId);\r\n              }\r\n              break;\r\n            case \"wallpaper-screen\":\r\n              // 外观设置页也需要重新渲染来应用新主题\r\n              renderWallpaperScreen();\r\n              break;\r\n            case \"font-settings-screen\":\r\n              // 字体预设页同样需要\r\n              renderFontPresets();\r\n              break;\r\n            // 如果未来还有其他页面需要适配，在这里添加 case 即可\r\n          }\r\n        }\r\n\r\n        /**\r\n         * 当用户点击开关时，切换当前的主题\r\n         */\r\n        function toggleTheme() {\r\n          const toggleSwitch = document.getElementById(\"theme-toggle-switch\");\r\n          // 直接根据开关的选中状态来决定新主题\r\n          const newTheme = toggleSwitch.checked ? \"dark\" : \"light\";\r\n          applyTheme(newTheme);\r\n        }\r\n        const fontPresetFaces = new Map();\r\n        let fontPreviewObserver = null;\r\n\r\n        function getSortedFontPresets(presets) {\r\n          return [...(presets || [])].sort((a, b) => {\r\n            const orderA = Number.isFinite(a.sortOrder) ? a.sortOrder : Infinity;\r\n            const orderB = Number.isFinite(b.sortOrder) ? b.sortOrder : Infinity;\r\n            return orderA - orderB || (a.createdAt || 0) - (b.createdAt || 0) ||\r\n              String(a.id).localeCompare(String(b.id));\r\n          });\r\n        }\r\n\r\n        function inferFontSourceType(url) {\r\n          return String(url || \"\").startsWith(\"data:\") ? \"local\" : \"url\";\r\n        }\r\n\r\n        function inferFontFormat(value) {\r\n          const source = String(value || \"\").toLowerCase().split(/[?#]/)[0];\r\n          const match = source.match(/\\.(woff2|woff|ttf|otf)$/);\r\n          return match ? match[1].toUpperCase() : \"字体文件\";\r\n        }\r\n\r\n        function formatFontSize(bytes) {\r\n          if (!Number.isFinite(bytes) || bytes <= 0) return \"大小未知\";\r\n          if (bytes < 1024 * 1024) return `${Math.max(1, Math.round(bytes / 1024))} KB`;\r\n          return `${(bytes / 1024 / 1024).toFixed(1)} MB`;\r\n        }\r\n\r\n        function escapeFontMarkup(value) {\r\n          return String(value ?? \"\")\r\n            .replaceAll(\"&\", \"&amp;\")\r\n            .replaceAll(\"<\", \"&lt;\")\r\n            .replaceAll(\">\", \"&gt;\")\r\n            .replaceAll('\"', \"&quot;\")\r\n            .replaceAll(\"'\", \"&#39;\");\r\n        }\r\n\r\n        function getFontFamilyName(id) {\n          const value = String(id);\n          let hash = 2166136261;\n          for (let index = 0; index < value.length; index += 1) {\n            hash ^= value.charCodeAt(index);\n            hash = Math.imul(hash, 16777619);\n          }\n          return `user-font-${(hash >>> 0).toString(36)}`;\n        }\n\r\n        async function loadFontFace(preset, forceReload = false) {\r\n          if (!preset?.url) throw new Error(\"字体来源为空\");\r\n          const key = String(preset.id);\r\n          if (!forceReload && fontPresetFaces.has(key)) {\r\n            return fontPresetFaces.get(key);\r\n          }\r\n          const family = getFontFamilyName(key);\r\n          const face = new FontFace(family, `url(${JSON.stringify(preset.url)})`);\r\n          const timeout = new Promise((_, reject) =>\r\n            setTimeout(() => reject(new Error(\"字体加载超时，请检查链接或网络\")), 15000),\r\n          );\r\n          const loadedFace = await Promise.race([face.load(), timeout]);\r\n          document.fonts.add(loadedFace);\r\n          const result = { face: loadedFace, family };\r\n          fontPresetFaces.set(key, result);\r\n          return result;\r\n        }\r\n\r\n        async function migrateFontPresetMetadata() {\r\n          const presets = await db.fontPresets.toArray();\r\n          const sorted = getSortedFontPresets(presets);\r\n          const updates = [];\r\n          sorted.forEach((preset, index) => {\r\n            const migrated = { ...preset };\r\n            let changed = false;\r\n            if (!Number.isFinite(migrated.sortOrder)) {\r\n              migrated.sortOrder = index;\r\n              changed = true;\r\n            }\r\n            if (!migrated.sourceType) {\r\n              migrated.sourceType = inferFontSourceType(migrated.url);\r\n              changed = true;\r\n            }\r\n            if (!migrated.format) {\r\n              migrated.format = inferFontFormat(migrated.url);\r\n              changed = true;\r\n            }\r\n            if (!migrated.createdAt) {\r\n              const timestamp = Number(String(migrated.id).match(/\\d+/)?.[0]);\r\n              migrated.createdAt = Number.isFinite(timestamp) ? timestamp : Date.now() + index;\r\n              changed = true;\r\n            }\r\n            if (changed) updates.push(migrated);\r\n          });\r\n          if (updates.length) await db.fontPresets.bulkPut(updates);\r\n        }\r\n\r\n        async function loadAllFontPresetsOnStartup() {\r\n          await migrateFontPresetMetadata();\r\n          let activeId = state.globalSettings?.fontPresetId;\r\n          const presets = await db.fontPresets.toArray();\r\n          const storedActive = activeId ? await db.fontPresets.get(activeId) : null;\r\n          if (!storedActive && state.globalSettings?.fontUrl) {\r\n            const matched = presets.find((preset) => preset.url === state.globalSettings.fontUrl);\r\n            if (matched) {\r\n              activeId = matched.id;\r\n              state.globalSettings.fontPresetId = matched.id;\r\n              await db.globalSettings.put(state.globalSettings);\r\n            }\r\n          }\r\n          if (activeId) {\r\n            const activePreset = await db.fontPresets.get(activeId);\r\n            if (activePreset) await loadFontFace(activePreset).catch(() => null);\r\n          }\r\n        }\r\n\r\n        function createFontButton(label, className, presetId, handler, disabled = false) {\r\n          const button = document.createElement(\"button\");\r\n          button.type = \"button\";\r\n          button.className = `preset-btn ${className}`.trim();\r\n          button.textContent = label;\r\n          button.dataset.presetId = String(presetId);\r\n          button.disabled = disabled;\r\n          button.onclick = handler;\r\n          return button;\r\n        }\r\n\r\n        async function renderFontPresets() {\r\n          const container = document.getElementById(\"font-preset-container\");\r\n          if (!container) return;\r\n          const allPresets = getSortedFontPresets(await db.fontPresets.toArray());\r\n          const searchInput = document.getElementById(\"font-library-search\");\r\n          const query = String(searchInput?.value || \"\").trim().toLocaleLowerCase();\r\n          const presets = query\r\n            ? allPresets.filter((preset) => String(preset.name || \"\").toLocaleLowerCase().includes(query))\r\n            : allPresets;\r\n          container.replaceChildren();\r\n\r\n          const count = document.getElementById(\"font-library-count\");\r\n          const localBytes = allPresets.reduce((sum, preset) => sum + (Number(preset.size) || 0), 0);\r\n          if (count) {\r\n            const totalLabel = localBytes > 0\r\n              ? `${allPresets.length} 个 · ${formatFontSize(localBytes)}`\r\n              : `${allPresets.length} 个字体`;\r\n            count.textContent = query ? `${presets.length}/${totalLabel}` : totalLabel;\r\n          }\r\n\r\n          const activeId = state.globalSettings?.fontPresetId;\r\n          const activePreset = activeId\r\n            ? allPresets.find((preset) => String(preset.id) === String(activeId))\r\n            : null;\r\n          const compatibleActivePreset = activePreset ||\r\n            allPresets.find((preset) => preset.url === state.globalSettings?.fontUrl);\r\n          const hasCompatibleCustomFont = !compatibleActivePreset && Boolean(state.globalSettings?.fontUrl);\r\n          const currentName = document.getElementById(\"font-current-name\");\r\n          const currentStatus = document.getElementById(\"font-current-status\");\r\n          if (currentName) currentName.textContent = compatibleActivePreset?.name ||\r\n            (hasCompatibleCustomFont ? \"自定义字体\" : \"默认字体\");\r\n          if (currentStatus) currentStatus.textContent = compatibleActivePreset\r\n            ? `${compatibleActivePreset.sourceType === \"local\" ? \"本地字体\" : \"URL 字体\"} · 已应用到全局`\r\n            : hasCompatibleCustomFont ? \"旧配置兼容模式 · 已应用到全局\" : \"使用应用默认字体\";\r\n\r\n          if (!presets.length) {\r\n            const empty = document.createElement(\"div\");\r\n            empty.className = \"font-preset-slot empty\";\r\n            empty.textContent = query\r\n              ? \"没有匹配的字体，请更换关键词\"\r\n              : \"字体库为空，可通过 URL 或本地文件添加\";\r\n            container.appendChild(empty);\r\n          }\r\n\r\n          presets.forEach((preset, index) => {\r\n            const actualIndex = allPresets.findIndex((item) => String(item.id) === String(preset.id));\r\n            const slot = document.createElement(\"article\");\r\n            slot.className = \"font-preset-slot\";\r\n\r\n            const preview = document.createElement(\"div\");\r\n            preview.className = \"font-preview-text\";\r\n            preview.dataset.presetId = String(preset.id);\r\n            preview.textContent = \"你好 Hello 123 · 字体预览\";\r\n\r\n            const info = document.createElement(\"div\");\r\n            info.className = \"font-preset-info\";\r\n            const nameRow = document.createElement(\"div\");\r\n            nameRow.className = \"font-preset-name-row\";\r\n            const name = document.createElement(\"span\");\r\n            name.className = \"font-preset-name\";\r\n            name.textContent = preset.name || \"未命名字体\";\r\n            name.title = name.textContent;\r\n            nameRow.appendChild(name);\r\n            if (compatibleActivePreset && String(compatibleActivePreset.id) === String(preset.id)) {\r\n              const badge = document.createElement(\"span\");\r\n              badge.className = \"font-preset-badge\";\r\n              badge.textContent = \"使用中\";\r\n              nameRow.appendChild(badge);\r\n            }\r\n            const meta = document.createElement(\"small\");\r\n            meta.className = \"font-preset-meta\";\r\n            meta.textContent = `${preset.sourceType === \"local\" ? \"本地\" : \"URL\"} · ${preset.format || inferFontFormat(preset.url)} · ${formatFontSize(preset.size)}`;\r\n            info.append(nameRow, meta);\r\n\r\n            const actions = document.createElement(\"div\");\r\n            actions.className = \"font-preset-actions\";\r\n            actions.append(\r\n              createFontButton(\"应用\", \"apply-btn\", preset.id, () => applyFontPreset(preset.id), Boolean(compatibleActivePreset && String(compatibleActivePreset.id) === String(preset.id))),\r\n              createFontButton(\"重命名\", \"secondary rename-btn\", preset.id, () => renameFontPreset(preset.id)),\r\n              createFontButton(\"上移\", \"secondary move-up-btn\", preset.id, () => moveFontPreset(preset.id, -1), actualIndex === 0 || Boolean(query)),\r\n              createFontButton(\"下移\", \"secondary move-down-btn\", preset.id, () => moveFontPreset(preset.id, 1), actualIndex === allPresets.length - 1 || Boolean(query)),\r\n              createFontButton(\"删除\", \"delete delete-btn\", preset.id, () => deleteFontPreset(preset.id)),\r\n            );\r\n            slot.append(preview, info, actions);\r\n            container.appendChild(slot);\r\n          });\r\n\r\n          if (fontPreviewObserver) fontPreviewObserver.disconnect();\r\n          if (\"IntersectionObserver\" in window) {\r\n            fontPreviewObserver = new IntersectionObserver((entries) => {\r\n              entries.forEach((entry) => {\r\n                if (!entry.isIntersecting) return;\r\n                const preset = allPresets.find((item) => String(item.id) === entry.target.dataset.presetId);\r\n                if (preset) loadFontForPreview(preset);\r\n                fontPreviewObserver.unobserve(entry.target);\r\n              });\r\n            }, { root: document.getElementById(\"font-settings-screen\"), rootMargin: \"120px\" });\r\n            container.querySelectorAll(\".font-preview-text\").forEach((element) => fontPreviewObserver.observe(element));\r\n          } else {\r\n            presets.forEach(loadFontForPreview);\r\n          }\r\n\r\n          addFontPresetButtonListeners();\r\n        }\r\n\r\n        async function loadFontForPreview(preset) {\r\n          const preview = [...document.querySelectorAll(\".font-preview-text\")]\r\n            .find((element) => element.dataset.presetId === String(preset.id));\r\n          if (!preview) return;\r\n          preview.dataset.loadState = \"loading\";\r\n          try {\r\n            const { family } = await loadFontFace(preset);\r\n            preview.style.fontFamily = `'${family}', 'bulangni', sans-serif`;\r\n            preview.dataset.loadState = \"loaded\";\r\n          } catch (error) {\r\n            preview.dataset.loadState = \"failed\";\r\n            preview.title = `加载失败：${error.message}`;\r\n            preview.textContent = \"字体加载失败，可删除后重新添加\";\r\n          }\r\n        }\r\n\r\n        function addFontPresetButtonListeners() {\r\n          const urlButton = document.getElementById(\"add-font-url-btn\");\r\n          const localButton = document.getElementById(\"add-font-local-btn\");\r\n          const searchInput = document.getElementById(\"font-library-search\");\r\n          const previewInput = document.getElementById(\"font-preview-input\");\r\n          if (urlButton) urlButton.onclick = handleUploadFontUrl;\r\n          if (localButton) localButton.onclick = handleUploadFontLocal;\r\n          if (searchInput) searchInput.oninput = renderFontPresets;\r\n          if (previewInput) previewInput.oninput = () => {\r\n            const heading = document.querySelector(\"#font-preview .font-preview-heading\");\r\n            if (heading) heading.textContent = previewInput.value.trim() || \"你好世界 Hello World 12345\";\r\n          };\r\n        }\r\n\r\n        async function handleUploadFontUrl() {\r\n          const value = await showCustomPrompt(\"字体URL\", \"请输入字体文件的 HTTPS 或 HTTP 直链\");\r\n          if (value === null) return;\r\n          let parsedUrl;\r\n          try {\r\n            parsedUrl = new URL(value.trim());\r\n            if (!/^https?:$/.test(parsedUrl.protocol)) throw new Error(\"protocol\");\r\n          } catch (_) {\r\n            await showCustomAlert(\"无法添加字体\", \"请输入有效的 HTTP 或 HTTPS 字体链接。\");\r\n            return;\r\n          }\r\n          const name = await showCustomPrompt(\"字体命名\", \"请为这个字体起个名字\");\r\n          if (!name?.trim()) {\r\n            if (name !== null) await showCustomAlert(\"无法添加字体\", \"字体名称不能为空。\");\r\n            return;\r\n          }\r\n          await saveFontPreset(name.trim(), parsedUrl.href, {\r\n            sourceType: \"url\",\r\n            format: inferFontFormat(parsedUrl.pathname),\r\n          });\r\n        }\r\n\r\n        function detectLocalFontFormat(buffer) {\r\n          const bytes = new Uint8Array(buffer.slice(0, 4));\r\n          const ascii = String.fromCharCode(...bytes);\r\n          if (ascii === \"wOF2\") return \"WOFF2\";\r\n          if (ascii === \"wOFF\") return \"WOFF\";\r\n          if (ascii === \"OTTO\") return \"OTF\";\r\n          if (bytes[0] === 0 && bytes[1] === 1 && bytes[2] === 0 && bytes[3] === 0) return \"TTF\";\r\n          return \"\";\r\n        }\r\n\r\n        function readFileAsDataUrl(file) {\r\n          return new Promise((resolve, reject) => {\r\n            const reader = new FileReader();\r\n            reader.onload = () => resolve(reader.result);\r\n            reader.onerror = () => reject(reader.error || new Error(\"无法读取字体文件\"));\r\n            reader.readAsDataURL(file);\r\n          });\r\n        }\r\n\r\n        function handleUploadFontLocal() {\r\n          const input = document.getElementById(\"font-preset-local-upload\");\r\n          input.value = \"\";\r\n          input.onchange = async (event) => {\r\n            const file = event.target.files?.[0];\r\n            if (!file) return;\r\n            try {\r\n              const header = await file.slice(0, 4).arrayBuffer();\r\n              const format = detectLocalFontFormat(header);\r\n              if (!format) {\r\n                await showCustomAlert(\r\n                  \"无法添加字体\",\r\n                  \"无法识别这个字体文件，请选择有效的 WOFF2、WOFF、TTF 或 OTF 文件。\",\r\n                );\r\n                return;\r\n              }\r\n              if (file.size > 12 * 1024 * 1024) {\r\n                const confirmed = await showCustomConfirm(\r\n                  \"字体文件较大\",\r\n                  `这个字体约 ${formatFontSize(file.size)}，保存和加载时可能较慢。是否继续？`,\r\n                );\r\n                if (!confirmed) return;\r\n              }\r\n              const name = await showCustomPrompt(\r\n                \"字体命名\",\r\n                \"请为这个字体起个名字\",\r\n                escapeFontMarkup(file.name.replace(/\\.[^/.]+$/, \"\")),\r\n              );\r\n              if (!name?.trim()) {\r\n                if (name !== null) await showCustomAlert(\"无法添加字体\", \"字体名称不能为空。\");\r\n                return;\r\n              }\r\n              const dataUrl = await readFileAsDataUrl(file);\r\n              await saveFontPreset(name.trim(), dataUrl, {\r\n                sourceType: \"local\",\r\n                format,\r\n                size: file.size,\r\n              });\r\n            } catch (error) {\r\n              console.error(\"读取本地字体失败:\", error);\r\n              await showCustomAlert(\"读取字体失败\", escapeFontMarkup(error.message));\r\n            } finally {\r\n              input.value = \"\";\r\n            }\r\n          };\r\n          input.click();\r\n        }\r\n\r\n        async function saveFontPreset(name, url, metadata = {}) {\r\n          const now = Date.now();\r\n          const id = `font_${globalThis.crypto?.randomUUID?.() || `${now}_${Math.random().toString(36).slice(2)}`}`;\r\n          const count = document.getElementById(\"font-library-count\");\r\n          if (count) count.textContent = \"正在验证字体…\";\r\n          try {\r\n            const presets = getSortedFontPresets(await db.fontPresets.toArray());\r\n            const newPreset = {\r\n              id,\r\n              name,\r\n              url,\r\n              sourceType: metadata.sourceType || inferFontSourceType(url),\r\n              format: metadata.format || inferFontFormat(url),\r\n              size: metadata.size || 0,\r\n              sortOrder: presets.length,\r\n              createdAt: now,\r\n              updatedAt: now,\r\n            };\r\n            await loadFontFace(newPreset, true);\r\n            await db.fontPresets.put(newPreset);\r\n            await renderFontPresets();\r\n            await showCustomAlert(\"字体已添加\", `“${escapeFontMarkup(name)}”已添加到字体库。`);\r\n          } catch (error) {\r\n            const loaded = fontPresetFaces.get(id);\r\n            if (loaded?.face) document.fonts.delete(loaded.face);\r\n            fontPresetFaces.delete(id);\r\n            console.error(\"保存字体预设失败:\", error);\r\n            await showCustomAlert(\r\n              \"字体未保存\",\r\n              `${escapeFontMarkup(error.message)}。原有字体数据未受影响。`,\r\n            );\r\n            await renderFontPresets();\r\n          }\r\n        }\r\n\r\n        async function renameFontPreset(presetId) {\r\n          const preset = await db.fontPresets.get(presetId);\r\n          if (!preset) return;\r\n          const name = await showCustomPrompt(\r\n            \"重命名字体\",\r\n            \"请输入新的字体名称\",\r\n            escapeFontMarkup(preset.name),\r\n          );\r\n          if (!name?.trim() || name.trim() === preset.name) return;\r\n          await db.fontPresets.update(presetId, { name: name.trim(), updatedAt: Date.now() });\r\n          await renderFontPresets();\r\n        }\r\n\r\n        async function moveFontPreset(presetId, direction) {\r\n          const presets = getSortedFontPresets(await db.fontPresets.toArray());\r\n          const index = presets.findIndex((preset) => String(preset.id) === String(presetId));\r\n          const targetIndex = index + direction;\r\n          if (index < 0 || targetIndex < 0 || targetIndex >= presets.length) return;\r\n          [presets[index], presets[targetIndex]] = [presets[targetIndex], presets[index]];\r\n          await db.fontPresets.bulkPut(presets.map((preset, order) => ({ ...preset, sortOrder: order })));\r\n          await renderFontPresets();\r\n        }\r\n\r\n        /**\r\n         * 删除一个字体预设\r\n         * @param {string} presetId - 要删除的预设的ID\r\n         */\r\n        async function deleteFontPreset(presetId) {\r\n          const preset = await db.fontPresets.get(presetId);\r\n          if (!preset) return;\r\n          const confirmed = await showCustomConfirm(\r\n            \"确认删除\",\r\n            \"确定要删除这个字体吗？删除后无法从字体库恢复。\",\r\n            {\r\n              confirmButtonClass: \"btn-danger\",\r\n            },\r\n          );\r\n          if (confirmed) {\r\n            const isActive = String(state.globalSettings?.fontPresetId || \"\") === String(presetId) ||\r\n              (!state.globalSettings?.fontPresetId && state.globalSettings?.fontUrl === preset.url);\r\n            if (isActive) await resetToDefaultFont(false);\r\n            await db.fontPresets.delete(presetId);\r\n            const loaded = fontPresetFaces.get(String(presetId));\r\n            if (loaded?.face) document.fonts.delete(loaded.face);\r\n            fontPresetFaces.delete(String(presetId));\r\n            const remaining = getSortedFontPresets(await db.fontPresets.toArray());\r\n            await db.fontPresets.bulkPut(remaining.map((item, order) => ({ ...item, sortOrder: order })));\r\n            await renderFontPresets();\r\n          }\r\n        }\r\n\r\n        /**\r\n         * 应用一个字体预设为全局字体\r\n         * @param {string} presetId - 要应用的预设的ID\r\n         */\r\n        async function applyFontPreset(presetId) {\r\n          const preset = await db.fontPresets.get(presetId);\r\n          if (preset) {\r\n            const applyButton = [...document.querySelectorAll(\".apply-btn\")]\r\n              .find((button) => button.dataset.presetId === String(presetId));\r\n            if (applyButton) {\r\n              applyButton.disabled = true;\r\n              applyButton.textContent = \"加载中\";\r\n            }\r\n            try {\r\n              await loadFontFace(preset);\r\n              const applied = await applyCustomFont(preset.url, false, preset.id);\r\n              if (!applied) throw new Error(\"字体无法应用\");\r\n              state.globalSettings.fontUrl = preset.url;\r\n              state.globalSettings.fontPresetId = preset.id;\r\n              await db.globalSettings.put(state.globalSettings);\r\n              await renderFontPresets();\r\n              await showCustomAlert(\r\n                \"字体已应用\",\r\n                `已将全局字体更换为“${escapeFontMarkup(preset.name)}”。`,\r\n              );\r\n            } catch (error) {\r\n              console.error(\"应用字体失败:\", error);\r\n              await showCustomAlert(\r\n                \"字体应用失败\",\r\n                `${escapeFontMarkup(error.message)}。当前字体保持不变。`,\r\n              );\r\n              await renderFontPresets();\r\n            }\r\n          }\r\n        }\r\n\r\n        /**\r\n         * 处理用户选择的角色卡文件\r\n         * @param {File} file - 用户选择的文件对象\r\n         */\r\n        async function handleCharacterImport(file) {\r\n          if (!file) return;\r\n\r\n          try {\r\n            let characterData;\r\n            let avatarBase64;\r\n\r\n            if (file.name.toLowerCase().endsWith(\".png\")) {\r\n              // 如果是PNG文件，调用PNG解析函数\r\n              const result = await parseCharPng(file);\r\n              characterData = result.characterData;\r\n              avatarBase64 = result.avatarBase64;\r\n            } else if (file.name.toLowerCase().endsWith(\".json\")) {\r\n              // 如果是JSON文件，调用JSON解析函数\r\n              characterData = await parseCharJson(file);\r\n              // JSON卡通常不包含图片，我们给一个默认头像\r\n              avatarBase64 = defaultAvatar;\r\n            } else {\r\n              alert(\"不支持的文件格式，请选择 .png 或 .json 文件。\");\r\n              return;\r\n            }\r\n\r\n            if (characterData) {\r\n              // 成功解析出数据后，调用创建函数\r\n              await createCharacterFromData(characterData, avatarBase64);\r\n            }\r\n          } catch (error) {\r\n            console.error(\"导入角色卡失败:\", error);\r\n            alert(`导入失败: ${error.message}`);\r\n          }\r\n        }\r\n\r\n        /**\r\n         * 解析SillyTavern的PNG角色卡，通过字节级操作彻底解决中文乱码问题。\r\n         * @param {File} file - PNG文件\r\n         * @returns {Promise<{characterData: object, avatarBase64: string}>}\r\n         */\r\n        async function parseCharPng(file) {\r\n          return new Promise((resolve, reject) => {\r\n            const reader = new FileReader();\r\n            reader.onload = (e) => {\r\n              const arrayBuffer = e.target.result;\r\n              const dataView = new DataView(arrayBuffer);\r\n\r\n              if (\r\n                dataView.getUint32(0) !== 0x89504e47 ||\r\n                dataView.getUint32(4) !== 0x0d0a1a0a\r\n              ) {\r\n                return reject(new Error(\"文件不是一个有效的PNG图片。\"));\r\n              }\r\n\r\n              let offset = 8;\r\n              let characterJson = null;\r\n\r\n              while (offset < dataView.byteLength) {\r\n                const length = dataView.getUint32(offset);\r\n                const type = String.fromCharCode(\r\n                  dataView.getUint8(offset + 4),\r\n                  dataView.getUint8(offset + 5),\r\n                  dataView.getUint8(offset + 6),\r\n                  dataView.getUint8(offset + 7),\r\n                );\r\n\r\n                if (type === \"tEXt\") {\r\n                  const chunkData = new Uint8Array(\r\n                    arrayBuffer,\r\n                    offset + 8,\r\n                    length,\r\n                  );\r\n\r\n                  // 1. 先用一个简单的编码将字节转为字符串，以便查找关键字 \"chara\"\r\n                  let text = \"\";\r\n                  for (let i = 0; i < chunkData.length; i++) {\r\n                    text += String.fromCharCode(chunkData[i]);\r\n                  }\r\n\r\n                  // 2. 检查关键字是否存在\r\n                  const keyword = \"chara\" + String.fromCharCode(0);\r\n                  if (text.startsWith(keyword)) {\r\n                    // 3. 提取出关键字后面的 Base64 编码的字符串\r\n                    const base64Data = text.substring(keyword.length);\r\n                    try {\r\n                      // 4. 使用 atob() 解码 Base64，得到一个“二进制字符串”\r\n                      const binaryString = atob(base64Data);\r\n\r\n                      // 5. 将这个“二进制字符串”重新转换为原始的 UTF-8 字节数组\r\n                      const bytes = new Uint8Array(binaryString.length);\r\n                      for (let i = 0; i < binaryString.length; i++) {\r\n                        bytes[i] = binaryString.charCodeAt(i);\r\n                      }\r\n\r\n                      // 6. 使用 TextDecoder 将这个纯净的 UTF-8 字节数组解码为正确的字符串\r\n                      const decodedJsonString = new TextDecoder(\"utf-8\").decode(\r\n                        bytes,\r\n                      );\r\n\r\n                      // 7. 解析最终的JSON字符串\r\n                      characterJson = JSON.parse(decodedJsonString);\r\n                      break;\r\n                    } catch (e) {\r\n                      return reject(\r\n                        new Error(\r\n                          \"解析图片内嵌的角色数据失败，可能是数据损坏。\",\r\n                        ),\r\n                      );\r\n                    }\r\n                  }\r\n                }\r\n\r\n                if (type === \"IEND\") break;\r\n                offset += 12 + length;\r\n              }\r\n\r\n              if (characterJson) {\r\n                const imageReader = new FileReader();\r\n                imageReader.onload = (imgEvent) => {\r\n                  resolve({\r\n                    characterData: characterJson,\r\n                    avatarBase64: imgEvent.target.result,\r\n                  });\r\n                };\r\n                imageReader.onerror = () =>\r\n                  reject(new Error(\"读取图片作为头像失败。\"));\r\n                imageReader.readAsDataURL(file);\r\n              } else {\r\n                reject(\r\n                  new Error(\"在这张PNG图片中没有找到SillyTavern角色数据。\"),\r\n                );\r\n              }\r\n            };\r\n            reader.onerror = () => reject(new Error(\"读取PNG文件失败。\"));\r\n            reader.readAsArrayBuffer(file);\r\n          });\r\n        }\r\n\r\n        /**\r\n         * 【修正版】解析JSON角色卡，强制使用UTF-8编码\r\n         * @param {File} file - JSON文件\r\n         * @returns {Promise<object>}\r\n         */\r\n        async function parseCharJson(file) {\r\n          return new Promise((resolve, reject) => {\r\n            const reader = new FileReader();\r\n            reader.onload = (e) => {\r\n              try {\r\n                // 先读取为ArrayBuffer，再用TextDecoder指定UTF-8解码\r\n                const arrayBuffer = e.target.result;\r\n                const textDecoder = new TextDecoder(\"utf-8\");\r\n                const jsonString = textDecoder.decode(arrayBuffer);\r\n                const data = JSON.parse(jsonString);\r\n                // 兼容两种可能的格式\r\n                resolve(data.data || data);\r\n              } catch (error) {\r\n                reject(new Error(\"解析JSON文件失败，请检查文件格式或编码。\"));\r\n              }\r\n            };\r\n            reader.onerror = () => reject(new Error(\"读取JSON文件失败。\"));\r\n            // 读取为ArrayBuffer而不是Text\r\n            reader.readAsArrayBuffer(file);\r\n          });\r\n        }\r\n\r\n        /**\r\n         * 根据解析出的数据创建新角色和世界书。\r\n         * 这个版本将优先查找您提供的 character_book 标准格式。\r\n         * @param {object} data - 从卡片解析出的最原始的JSON数据\r\n         * @param {string} avatarBase64 - 角色的头像图片 (Base64)\r\n         */\r\n        async function createCharacterFromData(data, avatarBase64) {\r\n          // 步骤 1: 确定核心角色数据 (不变)\r\n          const charData = data.data || data;\r\n          const characterName = charData.name\r\n            ? charData.name.trim()\r\n            : \"未命名角色\";\r\n\r\n          // 步骤 2: 创建新的聊天对象 (不变)\r\n          const newChatId = \"chat_\" + Date.now();\r\n\r\n          const newChat = {\r\n            id: newChatId,\r\n            name: characterName,\r\n            isGroup: false,\r\n            isPinned: false,\r\n            history: [],\r\n            unreadCount: 0,\r\n            musicData: { totalTime: 0 },\r\n            npcLibrary: [],\r\n            relationship: {\r\n              status: \"friend\",\r\n              blockedTimestamp: null,\r\n              applicationReason: \"\",\r\n            },\r\n            status: { text: \"在线\", lastUpdate: Date.now(), isBusy: false },\r\n            weiboDms: [],\r\n            loversSpaceData: null,\r\n            settings: {\r\n              aiPersona: charData.description || \"该角色没有描述。\",\r\n              myPersona: \"我是谁呀。\",\r\n              maxMemory: 10,\r\n              aiAvatar: avatarBase64,\r\n              myAvatar: defaultAvatar,\r\n              background: \"\",\r\n              theme: \"default\",\r\n              fontSize: 13,\r\n              customCss: \"\",\r\n              linkedWorldBookIds: [],\r\n              aiAvatarLibrary: [],\r\n              stickerLibrary: [],\r\n              summary: {\r\n                enabled: false,\r\n                mode: \"auto\",\r\n                count: 20,\r\n                prompt:\r\n                  \"请你以第三人称的视角，客观、冷静、不带任何感情色彩地总结以下对话的核心事件和信息。禁止进行任何角色扮演或添加主观评论。\",\r\n                lastSummaryIndex: -1,\r\n              },\r\n              linkedMemories: [],\r\n              offlineMode: {\r\n                enabled: false,\r\n                prompt: \"\",\r\n                style: \"\",\r\n                wordCount: 300,\r\n                presets: [],\r\n              },\r\n              timePerceptionEnabled: true,\r\n              customTime: \"\",\r\n              timeContext: {\r\n                enabled: true,\r\n                source: \"device\",\r\n                timeZone:\r\n                  window.TukTimeContext?.getDeviceTimeZone() || \"UTC\",\r\n                customTime: \"\",\r\n                gapAwareness: \"precise\",\r\n                customPrompt: \"\",\r\n              },\r\n              isCoupleAvatar: false,\r\n              coupleAvatarDescription: \"\",\r\n              weiboProfession: \"\",\n              weiboInstruction: \"\",\n              singleChatFeatures: {\n                innerVoice: false,\n                qzone: false,\n                weibo: false,\n                forum: false,\n                loversSpace: false,\n              },\n              visualVideoCallEnabled: false,\n              charVideoImage: \"\",\r\n              userVideoImage: \"\",\r\n              videoCallVoiceAccess: false,\r\n              petAdopted: false,\r\n              pet: null,\r\n            },\r\n            characterPhoneData: {\r\n              lastGenerated: null,\r\n              chats: {},\r\n              shoppingCart: [],\r\n              memos: [],\r\n              browserHistory: [],\r\n              photoAlbum: [],\r\n              bank: { balance: 0, transactions: [] },\r\n              trajectory: [],\r\n              appUsage: [],\r\n              diary: [],\r\n            },\r\n          };\r\n\r\n          await db.chats.put(newChat);\r\n          state.chats[newChatId] = newChat;\r\n\r\n          // 重构世界书查找逻辑\r\n          console.log(\"开始检测世界书数据...\");\r\n          let worldBookFound = false;\r\n\r\n          // 策略一：【最高优先级】查找提供的 character_book 标准格式\r\n          if (\r\n            charData.character_book &&\r\n            charData.character_book.entries &&\r\n            Array.isArray(charData.character_book.entries) &&\r\n            charData.character_book.entries.length > 0\r\n          ) {\r\n            console.log(\r\n              `检测到最新的 character_book 格式 (${charData.character_book.entries.length}条)，开始导入...`,\r\n            );\r\n            const newCategory = { name: characterName };\r\n            const newCategoryId = await db.worldBookCategories.add(newCategory);\r\n\r\n            await saveWorldBookEntriesFromArray(\r\n              charData.character_book.entries,\r\n              newCategoryId,\r\n            );\r\n            worldBookFound = true;\r\n          }\r\n\r\n          // 策略二：兼容旧的 world_entries 格式\r\n          else if (\r\n            charData.world_entries &&\r\n            Array.isArray(charData.world_entries) &&\r\n            charData.world_entries.length > 0\r\n          ) {\r\n            console.log(\r\n              `检测到旧版 world_entries 格式 (${charData.world_entries.length}条)，开始导入...`,\r\n            );\r\n            const newCategory = { name: characterName };\r\n            const newCategoryId = await db.worldBookCategories.add(newCategory);\r\n            await saveWorldBookEntriesFromArray(\r\n              charData.world_entries,\r\n              newCategoryId,\r\n            );\r\n            worldBookFound = true;\r\n          }\r\n\r\n          // 策略三：兼容更旧的 data.world 格式\r\n          else if (\r\n            data.world &&\r\n            typeof data.world === \"string\" &&\r\n            data.world.trim()\r\n          ) {\r\n            console.log(\"检测到外层 world 字段格式，开始导入...\");\r\n            const newCategory = { name: characterName };\r\n            const newCategoryId = await db.worldBookCategories.add(newCategory);\r\n            await saveWorldBookEntriesFromArray(\n              [{ name: characterName, content: data.world, constant: true }],\n              newCategoryId,\n            );\n            worldBookFound = true;\r\n          }\r\n\r\n          // 策略四：最后的兼容手段 world_info\r\n          else if (\r\n            charData.world_info &&\r\n            typeof charData.world_info === \"string\" &&\r\n            charData.world_info.trim()\r\n          ) {\r\n            console.log(\"检测到旧版 world_info 字段格式，开始导入...\");\r\n            const newCategory = { name: characterName };\r\n            const newCategoryId = await db.worldBookCategories.add(newCategory);\r\n            await saveWorldBookEntriesFromArray(\n              [\n                {\n                  name: characterName,\n                  content: charData.world_info,\n                  constant: true,\n                },\n              ],\n              newCategoryId,\n            );\n            worldBookFound = true;\r\n          }\r\n\r\n          if (!worldBookFound) {\r\n            console.log(\"诊断：在此角色卡中未找到任何可识别的世界书字段。\");\r\n          }\r\n\r\n          // 步骤 4: 刷新UI (不变)\r\n          await renderChatList();\r\n          await showCustomAlert(\r\n            \"导入成功！\",\r\n            `角色“${characterName}”已成功创建！`,\r\n          );\r\n        }\r\n\r\n        /**\r\n         * 从SillyTavern的 world_entries 或 character_book.entries 数组直接创建世界书\r\n         * @param {Array<object>} entriesArray - 包含世界书条目的数组\r\n         * @param {number} categoryId - 这些世界书所属的分类ID\r\n         */\r\n        async function saveWorldBookEntriesFromArray(entriesArray, categoryId) {\n          const validEntries = entriesArray.filter(\n            (entry) => entry && typeof entry.content === \"string\" && entry.content.trim(),\n          );\n          if (validEntries.length > 0) {\n            const category = await db.worldBookCategories.get(categoryId);\n            const newBook = window.TukWorldBook.normalizeBook(\n              {\n                name: category?.name || \"角色世界书\",\n                categoryId,\n                content: validEntries,\n                source: { type: \"character-card\", importedAt: Date.now() },\n              },\n              { source: \"character-card\" },\n            );\n            await db.worldBooks.add(newBook);\n            // 确保 state.worldBooks 也被更新，以便UI能立即显示\n            const allBooks = await db.worldBooks.toArray();\n            state.worldBooks = allBooks.map((book) =>\n              window.TukWorldBook.normalizeBook(book),\n            );\n            console.log(\n              `成功导入 1 本世界书和 ${validEntries.length} 个词条到分类ID: ${categoryId}`,\n            );\n          }\n        }\r\n\r\n        function getEventCoords(e) {\r\n          // 如果是触摸事件，就从 e.touches[0] 获取\r\n          if (e.touches && e.touches[0]) {\r\n            return { x: e.touches[0].pageX, y: e.touches[0].pageY };\r\n          }\r\n          // 否则，就是鼠标事件，直接从 e 获取\r\n          return { x: e.pageX, y: e.pageY };\r\n        }\r\n\r\n        function showScreen(screenId) {\r\n          if (\r\n            !document\r\n              .getElementById(\"logistics-screen\")\r\n              .classList.contains(\"active\")\r\n          ) {\r\n            logisticsUpdateTimers.forEach((timerId) => clearTimeout(timerId));\r\n            logisticsUpdateTimers = [];\r\n          }\r\n\r\n          if (screenId === \"chat-list-screen\") {\r\n            renderChatList();\r\n            switchToChatListView(\"messages-view\");\r\n          }\r\n          if (screenId === \"api-settings-screen\") {\r\n            renderApiSettings();\r\n          }\r\n          if (screenId === \"wallpaper-screen\") {\r\n            renderWallpaperScreen();\r\n          }\r\n          if (screenId === \"world-book-screen\") {\r\n            renderWorldBookScreen();\r\n          }\r\n          if (screenId === \"mcp-screen\") {\r\n            window.McpApp?.open();\r\n          }\r\n          if (screenId === \"thought-chain-screen\") {\n            window.ThoughtChainApp?.open();\n          }\n          if (screenId === \"prompt-center-screen\") {\n            window.PromptCenterApp?.open();\n          }\n\r\n          document\r\n            .querySelectorAll(\".screen\")\r\n            .forEach((s) => s.classList.remove(\"active\"));\r\n          const screenToShow = document.getElementById(screenId);\r\n          if (screenToShow) {\r\n            screenToShow.classList.add(\"active\");\r\n          }\r\n\r\n          if (screenId === \"chat-interface-screen\") {\r\n            updateListenTogetherIcon(state.activeChatId);\r\n          }\r\n\r\n          if (screenId === \"font-settings-screen\") {\r\n            document.getElementById(\"font-preview\").style.fontFamily = \"\";\r\n            applyCustomFont(\r\n              state.globalSettings.fontUrl || \"\",\r\n              true,\r\n              state.globalSettings.fontPresetId || \"active-preview\",\r\n            );\r\n            renderFontPresets();\r\n          }\r\n        }\r\n        window.showScreen = showScreen; // 确保 showScreen 自己也是全局的\r\n\r\n        window.updateListenTogetherIconProxy = () => {};\r\n\r\n        function switchToChatListView(viewId) {\r\n          const chatListScreen = document.getElementById(\"chat-list-screen\");\r\n          const views = {\r\n            \"messages-view\": document.getElementById(\"messages-view\"),\r\n            \"qzone-screen\": document.getElementById(\"qzone-screen\"),\r\n            \"favorites-view\": document.getElementById(\"favorites-view\"),\r\n            \"memories-view\": document.getElementById(\"memories-view\"), // <-- 新增这一行\r\n          };\r\n          const mainHeader = document.getElementById(\"main-chat-list-header\");\r\n          const mainBottomNav = document.getElementById(\"chat-list-bottom-nav\"); // 获取主导航栏\r\n\r\n          if (isFavoritesSelectionMode) {\r\n            document.getElementById(\"favorites-edit-btn\").click();\r\n          }\r\n\r\n          // 隐藏所有视图\r\n          Object.values(views).forEach((v) => v.classList.remove(\"active\"));\r\n          // 显示目标视图\r\n          if (views[viewId]) {\r\n            views[viewId].classList.add(\"active\");\r\n          }\r\n\r\n          // 更新底部导航栏高亮\r\n          document\r\n            .querySelectorAll(\"#chat-list-bottom-nav .nav-item\")\r\n            .forEach((item) => {\r\n              item.classList.toggle(\"active\", item.dataset.view === viewId);\r\n            });\r\n\r\n");
